import{_ as n,a,c as i,ac as r}from"./chunks/framework.BSuaGltH.js";const d=JSON.parse('{"title":"第二册：实践与进步 · 单元 1 语法总结 · 冠词与可数性至间接引语与视角转换","description":"L1–L24 规则、例句、易错点。","frontmatter":{"title":"第二册：实践与进步 · 单元 1 语法总结 · 冠词与可数性至间接引语与视角转换","description":"L1–L24 规则、例句、易错点。","splitFrom":"life/english/new-concept/book-2/unit-01/grammar.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第二册：实践与进步 · 单元 1 语法总结","summary":"L1–L24 规则、例句、易错点。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · 单元 1 语法总结 · 一般过去时与事件顺序至现在完成时与过去时间","link":"/life/english/new-concept/book-2/unit-01/grammar-part-01"},"next":{"text":"第二册：实践与进步 · 单元 1 语法总结 · 情态动词的意义与形式至动名词与动词搭配","link":"/life/english/new-concept/book-2/unit-01/grammar-part-03"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · 单元 1 语法总结 · 一般过去时与事件顺序至现在完成时与过去时间","link":"/life/english/new-concept/book-2/unit-01/grammar-part-01"},"next":{"text":"第二册：实践与进步 · 单元 1 语法总结 · 情态动词的意义与形式至动名词与动词搭配","link":"/life/english/new-concept/book-2/unit-01/grammar-part-03"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-01/grammar-part-02.md","filePath":"life/english/new-concept/book-2/unit-01/grammar-part-02.md"}'),t={name:"life/english/new-concept/book-2/unit-01/grammar-part-02.md"};function o(s,e,l,p,h,g){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="第二册-实践与进步-·-单元-1-语法总结-·-冠词与可数性至间接引语与视角转换" tabindex="-1">第二册：实践与进步 · 单元 1 语法总结 · 冠词与可数性至间接引语与视角转换 <a class="header-anchor" href="#第二册-实践与进步-·-单元-1-语法总结-·-冠词与可数性至间接引语与视角转换" aria-label="Permalink to &quot;第二册：实践与进步 · 单元 1 语法总结 · 冠词与可数性至间接引语与视角转换&quot;">​</a></h1><p><a href="/life/english/new-concept/book-2/unit-01/grammar">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-2/unit-01/overview">单元导读</a> · <a href="/life/english/new-concept/book-2/unit-01/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-2/unit-01/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-2/unit-01/review">单元复习与自测</a></p><h2 id="冠词与可数性" tabindex="-1">冠词与可数性 <a class="header-anchor" href="#冠词与可数性" aria-label="Permalink to &quot;冠词与可数性 {#冠词与可数性}&quot;">​</a></h2><p>a/an 引入一个尚未特指的可数单数名词，an 的选择取决于后面词的开头读音；the 用于听者能确定的对象或特定范围。泛指复数和不可数名词时常不用冠词。可数性也会随词义变化，如 coffee 可指饮料，也可指一杯饮料。不要把每个汉语名词都配上 a；先判断本句中的词义、数量及听者能否辨认对象。本课应用：先说 a neighbour 引入一位未确定的邻居，再说 the neighbour 指回同一人；bread 通常不可数，数量应通过 a slice of 表达。</p><p><strong>L6 原创例句：</strong> A neighbour brought me some bread after the storm.</p><p>暴风雨后，一位邻居给我送来了一些面包。</p><p><strong>易错：</strong> a bread 通常不能表示“一片面包”；用 a slice of bread，特定面包种类的用法另论。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-006">Lesson 6</a></p><h2 id="过去进行时与叙事背景" tabindex="-1">过去进行时与叙事背景 <a class="header-anchor" href="#过去进行时与叙事背景" aria-label="Permalink to &quot;过去进行时与叙事背景 {#过去进行时与叙事背景}&quot;">​</a></h2><p>过去进行时由 was/were 加动词 -ing 构成，描述过去某个时刻正在展开的活动。它常与一般过去时配合：进行时给出背景，过去式指出发生在背景中的事件。when 与 while 的选择取决于从句表达瞬间还是过程，不能把两者当作机械的时态开关。两个同时持续的活动也可都用进行时，而状态动词往往仍用简单时态。本课应用：were waiting 表示快递到达时仍持续的背景；arrived 给出发生的时间点。不要把两个动作都写成进行时而失去推动故事的事件。</p><p>过去进行时由 was/were 加动词 -ing 构成，描述过去某个时刻正在展开的活动。它常与一般过去时配合：进行时给出背景，过去式指出发生在背景中的事件。when 与 while 的选择取决于从句表达瞬间还是过程，不能把两者当作机械的时态开关。两个同时持续的活动也可都用进行时，而状态动词往往仍用简单时态。本课应用：was looking for 交代求助前正在寻找的过程；offered 是对方突然提供帮助的事件。理解失败不等于没有共同语言，要区分听懂单词与理解意思。</p><p><strong>L7 原创例句：</strong> The guards were checking the gate when the parcel arrived.</p><p>包裹送到时，守卫正在检查大门。</p><p><strong>L14 原创例句：</strong> I was looking for the station when a cyclist offered help.</p><p>我正在找车站时，一位骑车人主动提供了帮助。</p><p><strong>易错：</strong> The guards was checking 主谓不一致；checking 是活动，不应以 checked 代替 -ing 来构成进行时。</p><p>explain me the route 不符合常见搭配；用 explain the route to me。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-007">Lesson 7</a> · <a href="/life/english/new-concept/book-2/unit-01/lesson-014">Lesson 14</a></p><h2 id="比较级与比较范围" tabindex="-1">比较级与比较范围 <a class="header-anchor" href="#比较级与比较范围" aria-label="Permalink to &quot;比较级与比较范围 {#比较级与比较范围}&quot;">​</a></h2><p>比较两者时通常用比较级和 than；在明确的三者或更多成员中选出极值时通常用最高级。短形容词多加 -er/-est，较长形容词多用 more/most，good 与 bad 则是不规则变化。as ... as 中间用原级，否定形式表示不及。比较对象应属于同一类，范围和参照点必须清楚，不能只看到中文“最”就省掉比较范围。本课应用：smaller 比较面积，neater 比较整洁程度；不能因花园小就推断它差。最高级必须放在说明了成员范围的语境中。</p><p><strong>L8 原创例句：</strong> Lena&#39;s garden is smaller but neater than mine.</p><p>莉娜的花园比我的小，但更整洁。</p><p><strong>易错：</strong> Her garden is neater than me 比较对象不对称；用 than mine 或 than my garden。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-008">Lesson 8</a></p><h2 id="被动语态与信息重点" tabindex="-1">被动语态与信息重点 <a class="header-anchor" href="#被动语态与信息重点" aria-label="Permalink to &quot;被动语态与信息重点 {#被动语态与信息重点}&quot;">​</a></h2><p>被动语态由相应时态的 be 加过去分词构成，把动作的承受者放在主语位置。时态变化主要体现在 be 上，过去分词本身不随主语改变。只有可以带宾语的相关用法才能形成通常的被动句，happen、arrive 等不及物动词不能照搬。执行者未知、不重要或已经显然时可以省略 by 短语；需要追责或形成对比时则应保留。本课应用：was repaired 的焦点是吉他；若要说明谁修的，再补 by a local technician。不能把 repaired 单独放在名词后当完整谓语。</p><p>被动语态由相应时态的 be 加过去分词构成，把动作的承受者放在主语位置。时态变化主要体现在 be 上，过去分词本身不随主语改变。只有可以带宾语的相关用法才能形成通常的被动句，happen、arrive 等不及物动词不能照搬。执行者未知、不重要或已经显然时可以省略 by 短语；需要追责或形成对比时则应保留。本课应用：is disturbed 强调受到噪声干扰的人；planes disturb him 则强调执行者。选择语态取决于段落话题，不是被动一定比主动正式。</p><p>被动语态由相应时态的 be 加过去分词构成，把动作的承受者放在主语位置。时态变化主要体现在 be 上，过去分词本身不随主语改变。只有可以带宾语的相关用法才能形成通常的被动句，happen、arrive 等不及物动词不能照搬。执行者未知、不重要或已经显然时可以省略 by 短语；需要追责或形成对比时则应保留。本课应用：is being built 表当前正在施工，has been built 表已经建成。是否已经完成要看整个谓语结构，不是看到 built 就认为是过去时。</p><p><strong>L10 原创例句：</strong> The old guitar was repaired by a local technician.</p><p>那把旧吉他由一位当地技师修好了。</p><p><strong>L21 原创例句：</strong> Our sleep is disturbed by early flights.</p><p>我们的睡眠受到清晨航班的干扰。</p><p><strong>L23 原创例句：</strong> A new footpath is being built behind our house.</p><p>我们房子后面正在修建一条新的人行小路。</p><p><strong>易错：</strong> The guitar was belonged to me 错误；belong 表归属，用 The guitar belonged to me。</p><p>noise 与 noisy 词性不同：traffic noise 是噪声，a noisy street 是吵闹的街道。</p><p>is building 表主动建造，不能让 footpath 像施工者一样行动；此处用 is being built。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-010">Lesson 10</a> · <a href="/life/english/new-concept/book-2/unit-01/lesson-021">Lesson 21</a> · <a href="/life/english/new-concept/book-2/unit-01/lesson-023">Lesson 23</a></p><h2 id="将来表达与安排" tabindex="-1">将来表达与安排 <a class="header-anchor" href="#将来表达与安排" aria-label="Permalink to &quot;将来表达与安排 {#将来表达与安排}&quot;">​</a></h2><p>will 加动词原形可表达预测、意愿或当场决定；be going to 常表达已有打算或基于眼前证据的判断；现在进行时可描述已经落实的个人安排。表示时刻表也可用一般现在时。它们并不是严格的一对一中文翻译。时间和条件状语从句谈将来时，通常用现在时配合主句的将来表达，而不是把每个动词都加上 will。本课应用：is leaving 表示已落实的出发安排；will enjoy 可以表达对未来体验的预测。日期相同不意味着所有动词都必须使用同一种将来形式。</p><p><strong>L12 原创例句：</strong> Our neighbour is sailing to the island on Friday.</p><p>我们的邻居计划周五乘船前往那座岛。</p><p><strong>易错：</strong> sail to the island 表示去岛上；sail across the island 不符合船只在水面航行的通常语境。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-012">Lesson 12</a></p><h2 id="将来进行时与过程" tabindex="-1">将来进行时与过程 <a class="header-anchor" href="#将来进行时与过程" aria-label="Permalink to &quot;将来进行时与过程 {#将来进行时与过程}&quot;">​</a></h2><p>将来进行时使用 will be 加动词 -ing，突出未来某个时间正在发生的过程，常用于说明正常安排中的活动。它与 will do 的区别主要是观察角度：一个看过程，一个把动作看成整体。句中须有明确或可推知的未来参照时间。不要把 will be 后面接原形误当进行时，也不要用它保证某项活动一定完成；完成结果需要其他表达。本课应用：will be rehearsing 只说明明晚七点的过程，不说明排练什么时候结束。要表达完成时间，应另外给出 finish 或完成时结构。</p><p><strong>L13 原创例句：</strong> At seven tomorrow, the band will be rehearsing in the hall.</p><p>明天七点，乐队将在大厅里排练。</p><p><strong>易错：</strong> will rehearsing 缺少 be；will be rehearse 的动词形式也不对。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-013">Lesson 13</a></p><h2 id="间接引语与视角转换" tabindex="-1">间接引语与视角转换 <a class="header-anchor" href="#间接引语与视角转换" aria-label="Permalink to &quot;间接引语与视角转换 {#间接引语与视角转换}&quot;">​</a></h2><p>转述他人的话需要调整人称、时间和地点参照。主句为过去时且从过去视角回顾时，从句常相应后移时态；内容仍然有效或属于一般事实时，也可以保留现在时。陈述用 that 从句，是否问句用 if/whether，特殊疑问保留疑问词。转述疑问一律采用陈述语序，不保留原问句的助动词倒装；不能只换引号而不考虑说话视角。本课应用：said that 后可以直接接从句；told 通常先接听者。经理说 I 时指经理，转述时必须根据身份变更代词，不能照搬引号内的 I。</p><p><strong>L15 原创例句：</strong> The manager told Hana that her work was excellent.</p><p>经理告诉哈娜，她的工作表现很出色。</p><p><strong>易错：</strong> said Hana that 错误；说给某人听可用 said to Hana 或 told Hana。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-015">Lesson 15</a></p>',57)])])}const b=n(t,[["render",o]]);export{d as __pageData,b as default};
